"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["32453"],{5073(e,t,n){n.d(t,{Ay:()=>l,RM:()=>a});var s=n(74848),i=n(28453),o=n(66422);let a=[{value:"Zhou Zhijin, You Couldn&#39;t Even Get into College, and You&#39;re Still Showing Off?!",id:"zhou-zhijin-you-couldnt-even-get-into-college-and-youre-still-showing-off",level:3},{value:"Reply to Zhou Zhijin&#39;s Lengthy Response to &quot;Why I Didn&#39;t Want to Take the College Entrance Exam&quot;",id:"reply-to-zhou-zhijins-lengthy-response-to-why-i-didnt-want-to-take-the-college-entrance-exam",level:3},{value:"On the Zhou Zhijin Issue \u2014 Right-Wingers, It&#39;s Your Turn to Get a Trimming!",id:"on-the-zhou-zhijin-issue--right-wingers-its-your-turn-to-get-a-trimming",level:3}];function r(e){let t={blockquote:"blockquote",h1:"h1",h3:"h3",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"three-model-essays-on-striking-right-while-pretending-to-strike-left",children:'Three Model Essays on "Striking Right While Pretending to Strike Left"!'})}),"\n",(0,s.jsxs)(t.blockquote,{children:["\n",(0,s.jsx)(t.p,{children:"2006/4/28 21:50:09"}),"\n"]}),"\n",(0,s.jsxs)("div",{style:{textAlign:"center"},children:[(0,s.jsx)("img",{src:(0,o.Ay)("/img/essays/3samples/1.jpeg")}),(0,s.jsx)("br",{}),(0,s.jsx)("br",{})]}),"\n",(0,s.jsx)(t.p,{children:'Below are three essays written under the ID "Girl Who Likes Math" on the Zhou Zhijin issue:'}),"\n",(0,s.jsx)(t.h3,{id:"zhou-zhijin-you-couldnt-even-get-into-college-and-youre-still-showing-off",children:"Zhou Zhijin, You Couldn't Even Get into College, and You're Still Showing Off?!"}),"\n",(0,s.jsx)(t.p,{children:"Who Zhou Zhijin is, this girl has no interest in knowing \u2014 as long as it's a man, this girl must spit upon him. But a man who can't even get into college and still comes out to show off \u2014 that's not merely a manifestation of the innate defective nature of men, it more represents a personal problem. After all, before men are completely extinct, at least many of them can still get into college."}),"\n",(0,s.jsx)(t.p,{children:"In Zhou the man's account, he seems to have studied courses very diligently, which makes it supremely strange \u2014 how could diligent study still fail to get into college? Nowadays the college acceptance rate is so high that getting into college is simpler than eating a steamed bun. Some people never study seriously, yet seem to get into whatever they want \u2014 how can the gap between people be so vast?"}),"\n",(0,s.jsx)(t.p,{children:'Of course, it\'s not as if not attending college is some great problem \u2014 universities nowadays are essentially no different from certain special consumption establishments. But to sharpen one\'s head to squeeze in, even filing reports to audit classes at a university that\'s no different from certain consumption establishments \u2014 is this truly determined by nature? Of course, professors nowadays are no different from "call-beasts" [a pun: ji\xe0osh\xf2u means both \u6559\u6388 "professor" and \u53EB\u517D "screaming beast"], and cursing a couple of professors is no big deal. It\'s like in certain establishments where there\'s the issue of competing for favor \u2014 anyway men nowadays all enjoy this. Compete all you want, consume all you want, but to then file reports and come out showing off \u2014 that\'s too "Promise" [as in the film], or do men nowadays all enjoy eating steamed buns?'}),"\n",(0,s.jsx)(t.p,{children:"Although this girl is roughly the same age as Zhou \u2014 since I haven't investigated his exact age and don't want to compare who's older or younger \u2014 I still must advise this fellow: learn some real skills first. In terms of figure, you can't compare to Sister Mu or Sister Furong; in terms of learning, there are oceans of people above you. Those who go out to hustle must eventually pay their debts. Although this girl holds men in utter contempt, still, from the perspective of being in the same generation, let me waste a few words \u2014 don't make it so easy when this generation of feminism eliminates male power, or it won't be any fun."}),"\n",(0,s.jsx)(t.h3,{id:"reply-to-zhou-zhijins-lengthy-response-to-why-i-didnt-want-to-take-the-college-entrance-exam",children:"Reply to Zhou Zhijin's Lengthy Response to \"Why I Didn't Want to Take the College Entrance Exam\""}),"\n",(0,s.jsx)(t.p,{children:"This girl spent ten minutes writing \"Zhou Zhijin, You Couldn't Even Get into College, and You're Still Showing Off?!\" which upset the leftists and also drew out Zhou Zhijin's lengthy response today, \"Why I Didn't Want to Take the College Entrance Exam.\" Men take pride in length; this girl only loves slenderness and has no interest in long things. That post only proves that his failure to get into college was no accident, and that his judgment can only compete in the 4-to-5 age bracket (those who've tried it know)."}),"\n",(0,s.jsx)(t.p,{children:"Failing to get into college is just failing to get into college \u2014 there's really nothing to explain. Nowadays the difficulty of getting into college doesn't exceed that of eating a steamed bun. Would you write a lengthy response about whether or not you ate a bun? But if a person can't even get into a university that's inferior to a steamed bun, being called out is only natural. The prerequisite for rebelling against social conventions is that you're capable of fulfilling them; if you can't, then it's merely an unimpressive excuse. If a person got into a Tsinghua PhD at age five and then announced to the whole world, \"I despise Tsinghua\" \u2014 then the whole world would applaud, not despise. Conversely, if a person can't even get into a university that's inferior to a steamed bun, shouldn't being despised a little be expected?"}),"\n",(0,s.jsx)(t.p,{children:'The characteristic of men is their love of erecting chastity monuments \u2014 clearly enjoying a certain profession, they twist and squirm saying "no, no." If you don\'t want college, why go audit classes there? How is this different from claiming you don\'t want to engage in a certain profession while lingering at its doorstep every night? The characteristic of leftist men is pretending to know what they don\'t. Like their online banner-bearer "Mathematics" [a username], who replied under this girl\'s "Challenge All Men in the World \u2014 If I Lose, I\'ll Quit the Internet Immediately!" thinking that numbers in poetry can be made up as casually as his posts, not knowing that this girl\'s use of "three" could only be the uniquely level-toned "\u4E09" (s\u0101n), and "one reed" is an allusion that cannot be substituted. That\'s just how leftists are \u2014 forgive them!'}),"\n",(0,s.jsx)(t.p,{children:"As for the malicious slander against this girl using internet rumors in that response \u2014 just as leftists have always tried to link this girl with some \"Mathematics\" \u2014 this has essentially crossed into legal territory. Some day when this girl is in a bad mood, she can certainly play with legal weapons. However, just as with an egg-laying duck you can't kill the duck to take the eggs, things are so entertaining right now, so let's continue \u2014 this girl is very happy right now. As for Zhou the man saying this girl is very good with computers, this girl doesn't deserve such praise. Computers, like men, are merely things to be consumed. This girl never masters things meant for consumption \u2014 as long as they work, that's enough. Who'd bother mastering anything!"}),"\n",(0,s.jsx)(t.h3,{id:"on-the-zhou-zhijin-issue--right-wingers-its-your-turn-to-get-a-trimming",children:"On the Zhou Zhijin Issue \u2014 Right-Wingers, It's Your Turn to Get a Trimming!"}),"\n",(0,s.jsx)(t.p,{children:"This girl is anti-left, anti-right, anti-center, anti-men, anti-everything. Having gently trimmed the leftists a couple of days ago, not giving the rightists an equally gentle trimming would make them jealous and itchy, unable to sleep. On the Zhou Zhijin issue \u2014 right-wingers, it's your turn!"}),"\n",(0,s.jsx)(t.p,{children:"As everyone knows, when male ape-men encounter the stark-naked, call-beasts appear. One would have thought professors were like male ape-men \u2014 stark-nakedly being call-beasts! Only today do we discover that they can't even handle a Zhou Zhijin. Professors are indeed call-beasts, and full-time ones at that! A full-time professor is still a professor \u2014 scholars are the most useless of all. But which professor nowadays is a pushover? Without being a call-beast, without call-selling, how could one profess? Then it's supremely strange \u2014 these people who've fought their way up in the call-beast world, how can they not even handle one person who sharpened his head to squeeze in and audit their classes?"}),"\n",(0,s.jsx)(t.p,{children:"Don't prattle to this girl about humanity and dignity. The right-wingers' track record on humanity and dignity is known worldwide. You see Zhou Zhijin getting shamelessly famous \u2014 doesn't it make you itchy and jealous, unable to sleep? Jealous, aren't you? When you lick your American masters, you're so shameless that your tears soak through your underwear. Don't think you can be arrogant just because it's the Year of the Dog! Right-wingers act like grandsons on the surface while always looking for opportunities to recoup with interest \u2014 your little schemes are known to everyone on Earth!"}),"\n",(0,s.jsx)(t.p,{children:"Don't think the internet gives right-wingers their chance; don't think forums let you make your sly, snide remarks. Given the chance you'd bounce around a bit \u2014 give it up, your American daddy can barely save himself. He doesn't even know how he'll die someday, yet still swaggers around the world! Democracy what? Freedom what? One can say with certainty that once right-wingers get their chance, the blood they spill will be no less than the leftists'. What Hu Hansan looked like when he came back \u2014 even Martians know!"}),"\n",(0,s.jsx)(t.p,{children:"Right-wingers, how was this eight-minute post-trimming? Two minutes less than the leftists' ten \u2014 do not be jealous!"})]})}function l(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(r,{...e})}):r(e)}},77207(e,t,n){n.r(t),n.d(t,{metadata:()=>s,default:()=>g,frontMatter:()=>r,contentTitle:()=>l,toc:()=>u,assets:()=>h});var s=JSON.parse('{"id":"essays/3samples","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/essays/3samples.md","sourceDirName":"essays","slug":"/essays/3samples","permalink":"/en/essays/3samples","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"3samples","title":"","hide_table_of_contents":true,"sidebar_label":"Three Model Essays on \'Slapping the Left, Striking the Right\'! (2006/4/28 21:50:09)"},"sidebar":"essaysSidebar","previous":{"title":"Peddling Saviors and Great Liberators Is the True Spiritual Opium! (2006/4/23 18:32:41)","permalink":"/en/essays/spiritualopium"},"next":{"title":"Those Who Pontificate About \'Johns\' Are All Ignorant Fools! (2006/5/9 21:30:33)","permalink":"/en/essays/whoremasters"}}'),i=n(74848),o=n(28453),a=n(5073);let r={id:"3samples",title:"",hide_table_of_contents:!0,sidebar_label:"Three Model Essays on 'Slapping the Left, Striking the Right'! (2006/4/28 21:50:09)"},l,h={},u=[...a.RM];function d(e){return(0,i.jsx)(a.Ay,{})}function g(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},28453(e,t,n){n.d(t,{R:()=>a,x:()=>r});var s=n(96540);let i={},o=s.createContext(i);function a(e){let t=s.useContext(o);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),s.createElement(o.Provider,{value:t},e.children)}}}]);